/* --- TOKENS & RESET --- */
:root {
  --cream:        #FAF7F2;
  --cream-dark:   #F2EDE3;
  --cream-mid:    #EDE5D8;
  --brown-dark:   #3D2314;
  --brown-mid:    #6B3D22;
  --brown:        #8B5E3C;
